/**
 * Canonical Workbook-to-App Parity Synchronization: Edexcel GCSE Medicine
 * 
 * Synchronizes all 26 lessons in units/edexcel_medicine/data.js directly from
 * the 5 Key Topic two-page workbook compiler scripts:
 *   - scripts/render_medicine_medieval_twopage_workbook.cjs
 *   - scripts/render_medicine_renaissance_twopage_workbook.cjs
 *   - scripts/render_medicine_18th_19th_twopage_workbook.cjs
 *   - scripts/render_medicine_modern_twopage_workbook.cjs
 *   - scripts/render_medicine_western_front_twopage_workbook.cjs
 * 
 * Actions:
 * 1. Synchronizes lesson.exam_practice to match the exact questions, tariffs, stimuli,
 *    and scaffolding printed on the right-hand page (Recto) of each workbook spread.
 * 2. Purges conflicting/duplicate lesson.tasks arrays from GCSE lessons to eliminate
 *    the double accordion bug in the lesson renderer.
 * 3. Provides 100% historically rigorous Grade 9 Edexcel model answers for every task.
 */

const fs = require('fs');
const path = require('path');

const ROOT_DIR = path.join(__dirname, '..');

function extractVar(filePath, varName) {
  const content = fs.readFileSync(path.join(ROOT_DIR, filePath), 'utf8');
  const start = content.indexOf('const ' + varName + ' = [');
  if (start === -1) throw new Error('Not found ' + varName + ' in ' + filePath);
  const end = content.indexOf(';\n\nfunction', start);
  const code = content.substring(start + ('const ' + varName + ' = ').length, end !== -1 ? end : content.indexOf('];', start) + 1);
  return eval('(' + code + ')');
}

const medievalConfigs = extractVar('scripts/render_medicine_medieval_twopage_workbook.cjs', 'medievalConfigs');
const renaissanceConfigs = extractVar('scripts/render_medicine_renaissance_twopage_workbook.cjs', 'renaissanceConfigs');
const eighteenthNineteenthConfigs = extractVar('scripts/render_medicine_18th_19th_twopage_workbook.cjs', 'eighteenthNineteenthConfigs');
const modernConfigs = extractVar('scripts/render_medicine_modern_twopage_workbook.cjs', 'modernConfigs');
const wfConfigs = extractVar('scripts/render_medicine_western_front_twopage_workbook.cjs', 'wfConfigs');

const allConfigs = [
  ...medievalConfigs,
  ...renaissanceConfigs,
  ...eighteenthNineteenthConfigs,
  ...modernConfigs,
  ...wfConfigs
];

console.log(`Loaded ${allConfigs.length} canonical workbook configurations across all 5 Key Topics.`);

// Read and parse units/edexcel_medicine/data.js
const dataFilePath = path.join(ROOT_DIR, 'units', 'edexcel_medicine', 'data.js');
const rawText = fs.readFileSync(dataFilePath, 'utf8');
const jsonStr = rawText.replace(/^export default\s+/, '').replace(/;?\s*$/, '');
const unitData = JSON.parse(jsonStr);

if (!unitData.lessons || unitData.lessons.length !== 26) {
  throw new Error(`Expected 26 lessons in edexcel_medicine, found ${unitData.lessons ? unitData.lessons.length : 0}`);
}

